const body = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
const tenant_id = body.tenant_id;
const platform = (body.platform || 'youtube').toLowerCase();
const clip_id = body.clip_id;
const asset_version = body.asset_version;
if (!tenant_id || !clip_id || !asset_version) {
  throw new Error('LOOM_DIST_INVALID: missing tenant_id/clip_id/asset_version');
}
const schedule_date = body.schedule_date || null;
const title = body.title || null;
const summary = body.summary || null;
const privacy_level = body.privacy_level || 'unlisted';
const enc = encodeURIComponent;
return [{ json: {
  tenant_id, platform, clip_id, asset_version,
  schedule_date, title, summary, privacy_level,
  mapping_filter: `tenant_id=eq.${enc(tenant_id)}&platform=eq.${enc(platform)}`,
  media_filter: `tenant_id=eq.${enc(tenant_id)}&clip_id=eq.${enc(clip_id)}&asset_version=eq.${enc(asset_version)}`,
  review_filter: `tenant_id=eq.${enc(tenant_id)}&clip_id=eq.${enc(clip_id)}&asset_version=eq.${enc(asset_version)}&review_stage=eq.final_publication`,
} }];

const req = $('Preflight Guard').first().json;
const mapping = $('Load Tenant Mapping').first().json;
const enc = encodeURIComponent;
const receipt_filter = [
  `tenant_id=eq.${enc(req.tenant_id)}`,
  `platform=eq.${enc(req.platform)}`,
  `ghl_social_account_id=eq.${enc(mapping.ghl_social_account_id)}`,
  `clip_id=eq.${enc(req.clip_id)}`,
  `asset_version=eq.${enc(req.asset_version)}`,
].join('&');
return [{ json: { receipt_filter } }];

const rows = $('Load Existing Receipt').all() || [];
const successful = ['created','scheduled','published','reconciled'];
let receipt_state = 'none';
let existing_receipt = null;
// genuine receipt rows carry an id
const genuine = rows.filter(r => r && r.json && typeof r.json === 'object' && r.json.id);
if (genuine.length > 0) {
  existing_receipt = genuine[0].json;
  const st = (existing_receipt.status || '').toLowerCase();
  if (successful.includes(st)) receipt_state = 'distributed';
  else if (st === 'failed') receipt_state = 'failed';
  else receipt_state = 'ambiguous';
} else {
  // no genuine row: malformed (non-empty object without id) => ambiguous; empty placeholder => none
  const malformed = rows.filter(r => r && r.json && typeof r.json === 'object' && Object.keys(r.json).length > 0 && !r.json.id);
  receipt_state = malformed.length > 0 ? 'ambiguous' : 'none';
}
return [{ json: { receipt_state, existing_receipt } }];

const req = $('Preflight Guard').first().json;
const mapping = $('Load Tenant Mapping').first() ? $('Load Tenant Mapping').first().json : null;
const media = $('Load Media Asset').first() ? $('Load Media Asset').first().json : null;
const review = $('Load Final Review').first() ? $('Load Final Review').first().json : null;
const fail = (gate, detail) => { throw new Error(`LOOM_DIST_REJECT: ${gate} — ${detail}`); };
if (!mapping) fail('G1 connected', 'no tenant distribution mapping');
if (mapping.connection_status !== 'active') fail('G1 connected', `connection_status=${mapping.connection_status}`);
if (mapping.is_expired === true) fail('G1 connected', 'mapping is_expired=true');
if (mapping.entitled !== true) fail('G2 entitled', 'entitled !== true');
if (mapping.enabled_for_distribution !== true) fail('G3 enabled_for_distribution', 'enabled_for_distribution !== true');
if (!media) fail('G4 media approved', 'no loom_media row');
if (media.publication_status !== 'approved') fail('G4 media approved', `publication_status=${media.publication_status}`);
if (!media.publication_review_id) fail('G5 publication_review_id', 'null');
if (!review) fail('G6 review approve', 'no final_publication review row');
if (review.decision !== 'approve') fail('G6 review approve', `decision=${review.decision}`);
if (review.review_stage !== 'final_publication') fail('G7 review_stage', review.review_stage);
if (media.tenant_id !== req.tenant_id || media.clip_id !== req.clip_id || media.asset_version !== req.asset_version) fail('G8 identity', 'media identity mismatch');
if (review.tenant_id !== req.tenant_id || review.clip_id !== req.clip_id || review.asset_version !== req.asset_version) fail('G8 identity', 'review identity mismatch');
if (review.id !== media.publication_review_id) fail('G8 identity', 'review.id !== media.publication_review_id');
if (media.storage_status === 'fixture') fail('G9/G10 fixture', 'storage_status=fixture');
const SUPPORTED_MIME = ['video/mp4','video/quicktime','video/webm','video/x-m4v'];
if (!media.content_type) fail('G13 MIME', 'content_type is null/unknown');
if (!SUPPORTED_MIME.includes(media.content_type)) fail('G13 MIME', `content_type=${media.content_type} unsupported`);
if (req.schedule_date) {
  const d = new Date(req.schedule_date);
  if (isNaN(d.getTime())) fail('G12 schedule', 'invalid schedule_date');
}
return [{ json: { guard_passed: true } }];

const req = $('Preflight Guard').first().json;
const mapping = $('Load Tenant Mapping').first().json;
const media = $('Load Media Asset').first().json;
const ghl_location_id = mapping.ghl_location_id;
const ghl_social_account_id = mapping.ghl_social_account_id;
const profile_id = mapping.profile_id;
const publisher_user_id = mapping.publisher_user_id;
const canonical_url = media.canonical_url;
const media_type = media.content_type;
const title = req.title || media.source_filename || 'LOOM Distribution';
const summary = req.summary || title;
const privacy_level = req.privacy_level || 'unlisted';
const schedule_date = req.schedule_date || null;
const create_payload = {
  userId: publisher_user_id, accountIds: [ghl_social_account_id], summary,
  media: [{ url: canonical_url, type: media_type }], type: 'reel',
  status: schedule_date ? 'scheduled' : 'published',
  youtubePostDetails: { title, type: 'short', privacyLevel: privacy_level },
};
if (schedule_date) create_payload.scheduleDate = schedule_date;
return [{ json: { ghl_location_id, ghl_social_account_id, profile_id, create_payload } }];

const resp = $json;
const postId = resp && (resp.id || resp.postId || resp.post_id || (resp.post && resp.post.id));
const schedule_date = $('Preflight Guard').first().json.schedule_date;
let route, receipt_status;
if (resp && !resp.error && postId) { route = 'definitive'; receipt_status = schedule_date ? 'scheduled' : 'published'; }
else { route = 'ambiguous'; receipt_status = 'unknown'; }
return [{ json: { route, receipt_status, ghl_post_id: postId || null, create_response: resp } }];

const listResp = $json;
let posts = [];
if (Array.isArray(listResp)) posts = listResp;
else if (listResp && Array.isArray(listResp.posts)) posts = listResp.posts;
else if (listResp && Array.isArray(listResp.data)) posts = listResp.data;
else if (listResp && Array.isArray(listResp.accounts)) posts = listResp.accounts;
const reqTitle = (($('Preflight Guard').first().json.title) || '').toLowerCase();
let matched = null;
for (const p of posts) {
  const pid = p.id || p.postId || p._id;
  const pt = (p.title || p.summary || p.caption || '').toLowerCase();
  if (reqTitle && pt && pt.includes(reqTitle)) { matched = { id: pid, title: pt }; break; }
  if (pid && !reqTitle) { matched = { id: pid, title: pt }; break; }
}
let receipt_status, ghl_post_id, note;
if (matched && matched.id) { receipt_status = 'reconciled'; ghl_post_id = matched.id; note = 'matching post found via /posts/list'; }
else { receipt_status = 'unknown'; ghl_post_id = null; note = 'no matching post found; outcome unknown; no blind retry'; }
return [{ json: { receipt_status, ghl_post_id, reconcile_note: note, posts_seen: posts.length } }];

const req = $('Preflight Guard').first().json;
const mapping = $('Load Tenant Mapping').first().json;
const receipt_status = $json.receipt_status || 'unknown';
const ghl_post_id = $json.ghl_post_id || null;
const ghl_social_account_id = mapping.ghl_social_account_id;
const idempotency_key = `${req.tenant_id}:${req.platform}:${ghl_social_account_id}:${req.clip_id}:${req.asset_version}`;
const receipt_payload = {
  tenant_id: req.tenant_id, ghl_location_id: mapping.ghl_location_id, platform: req.platform,
  ghl_social_account_id, profile_id: mapping.profile_id, clip_id: req.clip_id,
  asset_version: req.asset_version, idempotency_key, ghl_post_id, status: receipt_status,
  scheduled_at: req.schedule_date || null,
  last_reconciled_at: (receipt_status === 'reconciled' || receipt_status === 'unknown') ? new Date().toISOString() : null,
};
return [{ json: { receipt_payload, receipt_status, ghl_post_id } }];
